 org.springframework.test.web.servlet.ResultActions mutate(String path,String key,String body)throws Exception{return client.mvc.perform(post(path).cookie(client.session,client.xsrf).header("X-XSRF-TOKEN",client.xsrf.getValue()).header("Idempotency-Key",key).contentType("application/json").content(body));}
 @Test void listDetailAreSafeOrderedAndBounded()throws Exception{var p=paid();client.getJson(base+"?site_id="+site.value()+"&status=SUCCEEDED&size=1").andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].payment_id").value(p.id().value().toString()));String detail=client.getJson(base+"/"+p.id().value()).andExpect(status().isOk()).andExpect(jsonPath("$.payment.status").value("SUCCEEDED")).andExpect(jsonPath("$.attempts").isArray()).andExpect(jsonPath("$.events").isArray()).andExpect(jsonPath("$.refunds").isArray()).andExpect(jsonPath("$.outbox_events").isArray()).andReturn().getResponse().getContentAsString();assertThat(detail).doesNotContain("config-ref","hash","ciphertext","metadata","lease","endpoint_url");client.getJson(base+"?size=101").andExpect(status().isBadRequest());client.getJson(base+"/"+UUID.randomUUID()).andExpect(status().isNotFound());}
 @Test void refundAcceptanceReplayAuditAndStrictBody()throws Exception{var p=paid();String path=base+"/"+p.id().value()+"/refunds";String body="{\"amount_minor\":700,\"currency\":\"EUR\",\"reason_code\":\"REQUESTED_BY_CUSTOMER\"}";String first=mutate(path,"key",body).andExpect(status().isAccepted()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.status").value("PROCESSING")).andReturn().getResponse().getContentAsString();assertThat(mutate(path,"key",body).andExpect(status().isAccepted()).andReturn().getResponse().getContentAsString()).isEqualTo(first);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_REFUND_REQUESTED'",Integer.class)).isEqualTo(1);client.postJson(path,body).andExpect(status().isBadRequest());mutate(path,"bad",body.replace("}",",\"secret\":\"hidden\"}")).andExpect(status().isBadRequest());}
