 @Test void fakeEventsOnlyEnqueueAndReplayDoesNotDuplicateAudit()throws Exception{var p=paid();String path=base+"/"+p.id().value()+"/fake-events";String body="{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":1}";String first=mutate(path,"event",body).andExpect(status().isAccepted()).andExpect(jsonPath("$.status").value("ACCEPTED")).andReturn().getResponse().getContentAsString();assertThat(mutate(path,"event",body).andExpect(status().isAccepted()).andReturn().getResponse().getContentAsString()).isEqualTo(first);assertThat(count("provider_inbox")).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='FAKE_PROVIDER_EVENT_SIMULATED'",Integer.class)).isEqualTo(1);}
