 @Test void filterPaginationSortAndUtcBoundsAreExplicit()throws Exception{var a=paid();var b=paid();var expected=jdbc.queryForList("select id::text from payments order by created_at desc,id desc",String.class);client.getJson(base+"?size=1&page=0").andExpect(jsonPath("$.total").value(2)).andExpect(jsonPath("$.items[0].payment_id").value(expected.getFirst()));client.getJson(base+"?size=1&page=1").andExpect(jsonPath("$.items[0].payment_id").value(expected.getLast()));client.getJson(base+"?sort=CREATED_ASC").andExpect(jsonPath("$.items[0].payment_id").value(expected.getLast()));client.getJson(base+"?payment_id="+a.id().value()+"&external_order_id="+a.externalOrderId()+"&provider=FAKE&created_from="+INITIAL_TIME+"&created_to="+INITIAL_TIME.plusSeconds(1)).andExpect(jsonPath("$.total").value(1));for(String query:List.of("size=0","page=-1","sort=id","created_from=2026-01-01T00:00:00%2B02:00","created_from="+INITIAL_TIME+"&created_to="+INITIAL_TIME))client.getJson(base+"?"+query).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store"));client.getJson(base+"?site_id="+UUID.randomUUID()).andExpect(jsonPath("$.total").value(0));}
 @Test void detailHasSafeOrderedRefundEventsAndActualReservedAvailability()throws Exception{var p=paid();var r=refunds.create(new CreateRefundCommand(site,p.id(),clientActor(),700,"EUR","OTHER","safe support note","one","request"));client.getJson(base+"/"+p.id().value()).andExpect(jsonPath("$.payment.refundable_amount_minor").value(1300)).andExpect(jsonPath("$.payment.refunded_amount_minor").value(0)).andExpect(jsonPath("$.events[0].sequence").value(1)).andExpect(jsonPath("$.events[1].sequence").value(2)).andExpect(jsonPath("$.refunds[0].id").value(r.id().value().toString())).andExpect(jsonPath("$.refunds[0].status").value("PROCESSING"));String json=client.getJson(base+"/"+p.id().value()).andReturn().getResponse().getContentAsString();assertThat(json).doesNotContain("technical_note","safe support note","operation_key","idempotency","request_fingerprint","return_url","config-ref");}
 UUID clientActor(){return UUID.fromString("30000000-0000-0000-0000-000000000001");}
 @ParameterizedTest @ValueSource(strings={"refunds","reconcile","fake-events"})
 void everyMutationRejectsDuplicateBlankOversizedHeadersWithoutWrites(String suffix)throws Exception{var p=paid();String body=suffix.equals("refunds")?"{\"amount_minor\":100,\"currency\":\"EUR\",\"reason_code\":\"OTHER\"}":suffix.equals("fake-events")?"{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":1}":"{}";String path=base+"/"+p.id().value()+"/"+suffix;for(String key:List.of(" ","x".repeat(256)))mutate(path,key,body).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store"));client.mvc.perform(post(path).cookie(client.session,client.xsrf).header("X-XSRF-TOKEN",client.xsrf.getValue()).header("Idempotency-Key","one","two").contentType("application/json").content(body)).andExpect(status().isBadRequest());assertThat(count("idempotency_records")).isZero();assertThat(count("refunds")).isZero();assertThat(count("provider_inbox")).isZero();}
 @ParameterizedTest @ValueSource(strings={"refunds","reconcile","fake-events"})
 void auditFailureRollsBackEachLocalAcceptance(String suffix)throws Exception{var p=paid();String body=suffix.equals("refunds")?"{\"amount_minor\":100,\"currency\":\"EUR\",\"reason_code\":\"OTHER\"}":suffix.equals("fake-events")?"{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":1}":"{}";var before=jdbc.queryForMap("select * from fake_provider_objects");rejectWrite("audit_log","insert","true");mutate(base+"/"+p.id().value()+"/"+suffix,"rollback",body).andExpect(status().isConflict());assertThat(count("idempotency_records")).isZero();assertThat(count("refunds")).isZero();assertThat(count("provider_inbox")).isZero();assertThat(count("payment_events")).isZero();assertThat(jdbc.queryForMap("select * from fake_provider_objects")).isEqualTo(before);}
 @Test void fakeRefundOnlyEnqueuesThenSharedWorkerAppliesAndIdempotencyConflictIsEarly()throws Exception{var p=paid();var r=refunds.create(new CreateRefundCommand(site,p.id(),clientActor(),700,"EUR","OTHER",null,"refund","request"));String path=base+"/"+p.id().value()+"/fake-events";String body="{\"target\":\"REFUND\",\"refund_id\":\""+r.id().value()+"\",\"event_type\":\"REFUND_SUCCEEDED\",\"sequence\":2}";mutate(path,"event",body).andExpect(status().isAccepted());assertThat(load.findById(site,p.id()).orElseThrow().refundedAmountMinor()).isZero();mutate(path,"event",body.replace("2}","3}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("IDEMPOTENCY_CONFLICT"));assertThat(count("provider_inbox")).isEqualTo(1);worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.PARTIALLY_REFUNDED);}
 @ParameterizedTest @ValueSource(strings={"{\"target\":\"PAYMENT\",\"event_type\":\"REFUND_SUCCEEDED\",\"sequence\":1}","{\"target\":\"REFUND\",\"event_type\":\"REFUND_SUCCEEDED\",\"sequence\":1}","{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":0}","{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":1,\"occurred_at\":\"2099-01-01T00:00:00Z\"}"})
 void invalidFakeControlsRejectBeforeIdempotency(String body)throws Exception{var p=paid();mutate(base+"/"+p.id().value()+"/fake-events","invalid",body).andExpect(status().isBadRequest());assertThat(count("provider_inbox")).isZero();assertThat(count("idempotency_records")).isZero();}
 @Test void inactiveSiteReconcilePreflightCannotCreateReceiptOrAudit()throws Exception{var p=paid();jdbc.update("update sites set status='DISABLED' where id=?",site.value());mutate(base+"/"+p.id().value()+"/reconcile","inactive","{}").andExpect(status().isConflict());assertThat(count("idempotency_records")).isZero();assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_RECONCILIATION_REQUESTED'",Integer.class)).isZero();}
 @Test void reconciliationReplayReturnsCurrentProjectionWithoutDuplicateAudit()throws Exception{var p=paid();state.setPaymentState(request(p),ProviderState.Status.SUCCEEDED);String path=base+"/"+p.id().value()+"/reconcile";mutate(path,"reconcile","{}").andExpect(status().isOk()).andExpect(jsonPath("$.payment.status").value("SUCCEEDED"));var receipt=jdbc.queryForMap("select * from idempotency_records");assertThat(receipt.get("response_status")).isEqualTo(202);mutate(path,"reconcile","{}").andExpect(status().isOk());assertThat(jdbc.queryForMap("select * from idempotency_records")).isEqualTo(receipt);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_RECONCILIATION_REQUESTED'",Integer.class)).isEqualTo(1);}
 @Test void validationProblemsUseStage2SafeCodesAndFieldErrors()throws Exception{var p=paid();String path=base+"/"+p.id().value()+"/refunds";mutate(path,"fields","{}").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("PAYMENT_REQUEST_INVALID")).andExpect(jsonPath("$.field_errors[0].code").value("INVALID_VALUE"));mutate(path,"json","{\"unknown_secret\":\"Bearer hidden\"}").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("PAYMENT_REQUEST_INVALID"));assertThat(count("idempotency_records")).isZero();}
 @Test void nonFakeControlRejectsWithoutReceiptProviderMutationInboxOrAudit()throws Exception{var p=paid();jdbc.update("update payment_accounts set provider='STRIPE' where id=?",account.id().value());mutate(base+"/"+p.id().value()+"/fake-events","nonfake","{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":1}").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("PROVIDER_CAPABILITY_UNAVAILABLE"));assertThat(count("idempotency_records")).isZero();assertThat(count("provider_inbox")).isZero();assertThat(jdbc.queryForObject("select count(*) from audit_log where action='FAKE_PROVIDER_EVENT_SIMULATED'",Integer.class)).isZero();assertThat(jdbc.queryForObject("select event_counter from fake_provider_objects",Integer.class)).isZero();}
 @Test void reconciliationLiveLeaseReceiptIsImmutableAndExpiredRetryResumes()throws Exception{var p=paid();jdbc.update("update payments set reconciliation_lease_owner=?,reconciliation_lease_expires_at=? where id=?",UUID.randomUUID(),java.sql.Timestamp.from(INITIAL_TIME.plusSeconds(30)),p.id().value());String path=base+"/"+p.id().value()+"/reconcile";mutate(path,"leased","{}").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("PAYMENT_STATE_CONFLICT"));var receipt=jdbc.queryForMap("select * from idempotency_records");assertThat(receipt.get("status")).isEqualTo("COMPLETED");assertThat(receipt.get("response_status")).isEqualTo(202);dev.genericpayments.platform.support.PostgresIntegrationTest.TestClock.set(INITIAL_TIME.plusSeconds(31));mutate(path,"leased","{}").andExpect(status().isOk());assertThat(jdbc.queryForMap("select * from idempotency_records")).isEqualTo(receipt);assertThat(jdbc.queryForObject("select count(*) from audit_log where action='PAYMENT_RECONCILIATION_REQUESTED'",Integer.class)).isEqualTo(1);}
 @Test void unavailableRefundProviderIsStableStateConflictBeforeWrites()throws Exception{var p=paid();jdbc.update("update payment_accounts set provider='STRIPE' where id=?",account.id().value());mutate(base+"/"+p.id().value()+"/refunds","nonfake","{\"amount_minor\":100,\"currency\":\"EUR\",\"reason_code\":\"OTHER\"}").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("PAYMENT_STATE_CONFLICT"));assertThat(count("idempotency_records")).isZero();assertThat(count("refunds")).isZero();}
 @Test void fakeDuplicateAndOutOfOrderFactsDoNotReplaceTerminalTruth()throws Exception{var p=paid();String path=base+"/"+p.id().value()+"/fake-events";String success="{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_SUCCEEDED\",\"sequence\":3}";mutate(path,"success",success).andExpect(status().isAccepted());mutate(path,"duplicate",success).andExpect(status().isAccepted());mutate(path,"late","{\"target\":\"PAYMENT\",\"event_type\":\"PAYMENT_FAILED\",\"sequence\":2}").andExpect(status().isAccepted());assertThat(count("provider_inbox")).isEqualTo(2);assertThat(jdbc.queryForObject("select state from fake_provider_objects",String.class)).isEqualTo("SUCCEEDED");worker.runOnce();assertThat(load.findById(site,p.id()).orElseThrow().status()).isEqualTo(PaymentStatus.SUCCEEDED);assertThat(count("payment_events")).isZero();}
 @Autowired dev.genericpayments.platform.payments.application.port.out.SavePaymentAttemptPort attemptSave;
 @Autowired dev.genericpayments.platform.webhooks.application.port.out.CallbackConfigurationPort callbacks;
 @Autowired dev.genericpayments.platform.webhooks.application.port.out.OutboxPort outbox;
 @Autowired tools.jackson.databind.ObjectMapper mapper;
 @Test void detailOrdersAllChildrenAndSeparatesOtherPaymentAndSiteFacts()throws Exception{
  var p=paid();var other=paid();var otherSite=UUID.randomUUID();
  jdbc.update("insert into sites(id,site_key,display_name,status,payment_account_id,payment_method_policy,created_at,updated_at,version) values (?,'other-site','Other','ACTIVE',?,'AUTOMATIC',?,?,0)",otherSite,account.id().value(),java.sql.Timestamp.from(INITIAL_TIME),java.sql.Timestamp.from(INITIAL_TIME));
  save.save(Payment.dynamic(new PaymentId(UUID.randomUUID()),new dev.genericpayments.platform.sites.domain.SiteId(otherSite),account.id(),"other",dev.genericpayments.platform.catalog.domain.Money.of(2000,"EUR"),dev.genericpayments.platform.catalog.domain.TaxMode.NONE,Map.of(),INITIAL_TIME));
  for(int number:List.of(2,1)){var id=new PaymentAttemptId(UUID.randomUUID());attemptSave.insert(PaymentAttempt.start(id,p.id(),number,"operation-"+number,"CARD",INITIAL_TIME).failed("DECLINED",INITIAL_TIME),INITIAL_TIME);}
  callbacks.configure(site.value(),"https://example.com/callback",true);
  refunds.create(new CreateRefundCommand(site,p.id(),clientActor(),500,"EUR","OTHER",null,"one","request"));refunds.create(new CreateRefundCommand(site,p.id(),clientActor(),600,"EUR","OTHER",null,"two","request"));refunds.create(new CreateRefundCommand(site,other.id(),clientActor(),100,"EUR","OTHER",null,"other","request"));
  for(var claim:outbox.claimAutomatic("detail",100,INITIAL_TIME,java.time.Duration.ofSeconds(30)))outbox.complete(claim,dev.genericpayments.platform.webhooks.application.port.out.CallbackHttpPort.Result.failed(500,dev.genericpayments.platform.webhooks.application.port.out.CallbackHttpPort.ErrorCategory.HTTP_STATUS),INITIAL_TIME);
  for(var claim:outbox.claimAutomatic("detail",100,INITIAL_TIME.plusSeconds(60),java.time.Duration.ofSeconds(30)))outbox.complete(claim,dev.genericpayments.platform.webhooks.application.port.out.CallbackHttpPort.Result.success(204),INITIAL_TIME.plusSeconds(60));
  var result=client.getJson(base+"/"+p.id().value()).andExpect(status().isOk()).andExpect(jsonPath("$.attempts[0].attempt_number").value(1)).andExpect(jsonPath("$.attempts[1].attempt_number").value(2)).andExpect(jsonPath("$.refunds.length()").value(2)).andExpect(jsonPath("$.events.length()").value(4)).andExpect(jsonPath("$.outbox_events.length()").value(2)).andExpect(jsonPath("$.deliveries.length()").value(4));
  var document=mapper.readTree(result.andReturn().getResponse().getContentAsString());
  var refundIds=jdbc.queryForList("select id::text from refunds where payment_id=? order by created_at,id",String.class,p.id().value());assertThat(document.path("refunds").get(0).path("id").asText()).isEqualTo(refundIds.getFirst());
  var outboxIds=jdbc.queryForList("select id::text from outbox_events where payment_id=? order by created_at,id",String.class,p.id().value());assertThat(document.path("outbox_events").get(0).path("id").asText()).isEqualTo(outboxIds.getFirst());
  var deliveryIds=jdbc.queryForList("select d.id::text from outbox_deliveries d join outbox_events e on e.id=d.outbox_event_id where e.payment_id=? order by d.attempt_number,d.id",String.class,p.id().value());for(int i=0;i<deliveryIds.size();i++)assertThat(document.path("deliveries").get(i).path("id").asText()).isEqualTo(deliveryIds.get(i));
  assertThat(document.toString()).doesNotContain("https://example.com","ciphertext","payload","operation-","other-site","technical_note");client.getJson(base+"?site_id="+site.value()).andExpect(jsonPath("$.total").value(2));client.getJson(base+"?site_id="+otherSite).andExpect(jsonPath("$.total").value(1));
 }
 @Test void unsafeDomainRequestUsesStage2CodeAndExtremeUtcBoundsAreRejected()throws Exception{var p=paid();mutate(base+"/"+p.id().value()+"/refunds","unsafe","{\"amount_minor\":100,\"currency\":\"EUR\",\"reason_code\":\"OTHER\",\"technical_note\":\"4111111111111111\"}").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("PAYMENT_REQUEST_INVALID"));client.mvc.perform(get(base).cookie(client.session).param("created_to","+1000000000-12-31T23:59:59.999999999Z")).andExpect(status().isBadRequest());assertThat(count("idempotency_records")).isZero();}
